using System;using System.Drawing;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
partial class AvalonInterno {
 TextBox partyKey=new TextBox();Keys partyChoice=Keys.F6;bool partyCtrl,partyAlt,partyShift;CancellationTokenSource partyCancel;
 string PartyKeyText(){return(partyCtrl?"Ctrl+":"")+(partyAlt?"Alt+":"")+(partyShift?"Shift+":"")+partyChoice;}
 void PartyKeyEditor(int x,int y){partyKey.SetBounds(x,y,58,16);partyKey.ReadOnly=true;partyKey.BorderStyle=BorderStyle.None;partyKey.Text=PartyKeyText();partyKey.TextAlign=HorizontalAlignment.Center;partyKey.BackColor=Color.Black;partyKey.ForeColor=Color.Cyan;partyKey.Font=new Font("Segoe UI",(float)(8)*global::UiScale.F);partyKey.KeyDown+=(o,e)=>{e.SuppressKeyPress=true;if(e.KeyCode==Keys.ControlKey||e.KeyCode==Keys.ShiftKey||e.KeyCode==Keys.Menu)return;partyChoice=e.KeyCode;partyCtrl=e.Control;partyAlt=e.Alt;partyShift=e.Shift;partyKey.Text=PartyKeyText();Save();};Controls.Add(partyKey);hints.SetToolTip(partyKey,"Clique e pressione a tecla para Montar PT. Padrão: F6.");}
 void PartyButton(){var button=ButtonAt("Montar PT",270,408,143,()=>{var task=MakeParty();});button.Height=29;hints.SetToolTip(button,"O principal convida os secundários selecionados; o app confirma a entrada no grupo.");}
 void BindParty(){BindBuff();BindRemount();partyKey.Text=PartyKeyText();Win.UnregisterHotKey(Handle,2);if(!shortcutActive||!gameInFront||controlLocked)return;uint mods=0x4000|(partyCtrl?2u:0u)|(partyAlt?1u:0u)|(partyShift?4u:0u);Note(Win.RegisterHotKey(Handle,2,mods,(uint)partyChoice)?"Montar PT: atalho "+PartyKeyText():"Tecla de Montar PT ocupada; escolha outra.");}
 void CancelParty(){if(partyCancel!=null)partyCancel.Cancel();CancelBuffWait();}
 async Task MakeParty(){if(closeInProgress)return;CancelBuffWait();await YieldFollowRepair();if(busy||teleport.Working||missions.Working){Note("Aguarde a operação atual para montar PT.");return;}var primary=main.SelectedItem as Entry;if(primary==null){Note("Escolha o principal.");return;}var selected=followers.CheckedItems.Cast<Entry>().Where(rz=>!RotaLock.Busy(rz.Pid)).Where(e=>e.Pid!=primary.Pid&&ProcessAlive(e.Pid)).ToArray();if(selected.Length==0){Note("Selecione os secundários para montar PT.");return;}if(blocked.Contains(primary.Pid)){Note("Reinicie o cliente principal: ponte anterior não confirmou remoção.");return;}
  busy=true;action.Enabled=false;partyCancel=new CancellationTokenSource();var token=partyCancel.Token;var progress=new Progress<string>(s=>Note(s));try{await StopAttacks();foreach(var skip in selected.Where(sz=>blocked.Contains(sz.Pid)))Note(skip.Name+": reinicie esse cliente antes de tentar novamente.");var refs=selected.Where(sz=>!blocked.Contains(sz.Pid)).Select(sz=>sz.Ref()).ToList();var primaryRef=primary.Ref();var results=await Task.Run(()=>PartyService.JoinAll(primaryRef,refs,token,(IProgress<string>)progress));foreach(var result in results){if(result.Message!=null)Note(result.Message);if(result.Blocked)blocked.Add(result.Pid);}status.Text=token.IsCancellationRequested?"Montagem da PT cancelada":"Montar PT concluído · consulte o registro";}
  catch(Exception e){Note("Montar PT: "+e.Message);}finally{partyCancel.Dispose();partyCancel=null;busy=false;action.Enabled=true;}
 }
}
